#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;            // a musi być przed b
        g[a].push_back(b);
        indeg[b]++;
    }
    queue<int> q;
    for (int v = 1; v <= n; v++)
        if (indeg[v] == 0) q.push(v);
    vector<int> order;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        order.push_back(v);
        for (int u : g[v])
            if (--indeg[u] == 0) q.push(u);
    }
    if ((int)order.size() < n) {
        cout << "CYKL\n";         // nie da się ustawić
        return 0;
    }
    for (int v : order) cout << v << ' ';
    cout << '\n';
}

const int MAXN = 200005;
vector<int> g[MAXN];
int color[MAXN];          // 0 nieodwiedzony, 1 na stosie, 2 gotowy
vector<int> post;
bool cykl = false;

void dfs(int v) {
    color[v] = 1;
    for (int u : g[v]) {
        if (color[u] == 0) dfs(u);
        else if (color[u] == 1) cykl = true;
    }
    color[v] = 2;
    post.push_back(v);    // wychodzimy z v: wszystkie jego następniki już są w post
}

vector<int> toposortDfs(int n) {
    for (int v = 1; v <= n; v++) if (color[v] == 0) dfs(v);
    reverse(post.begin(), post.end());
    return post;          // gdy cykl == true, wynik nie jest poprawnym porządkiem
}

