#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> g(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});
        indeg[b]++;
    }
    // porządek topologiczny (Kahn)
    vector<int> order;
    queue<int> q;
    for (int v = 1; v <= n; v++) if (indeg[v] == 0) q.push(v);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        order.push_back(v);
        for (auto [u, w] : g[v]) if (--indeg[u] == 0) q.push(u);
    }

    vector<long long> best(n + 1, 0);   // najdłuższa ścieżka KOŃCZĄCA się w v (start dowolny)
    vector<long long> cnt(n + 1, 0);    // liczba ścieżek 1 -> v
    cnt[1] = 1;
    for (int v : order)
        for (auto [u, w] : g[v]) {
            best[u] = max(best[u], best[v] + w);
            cnt[u] = (cnt[u] + cnt[v]) % MOD;
        }
    cout << *max_element(best.begin(), best.end()) << '\n';
    cout << cnt[n] << '\n';
}

// Memoizacja: dp[v] = najdłuższa ścieżka (liczba krawędzi) ZACZYNAJĄCA się w v.
const int MAXN = 200005;
vector<int> g[MAXN];
int dp[MAXN];
bool done[MAXN];

int longest(int v) {
    if (done[v]) return dp[v];
    done[v] = true;
    dp[v] = 0;
    for (int u : g[v]) dp[v] = max(dp[v], longest(u) + 1);
    return dp[v];
}

