#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = LLONG_MAX / 4;          // zapas, żeby INF + w się nie przepełniło

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> g(n + 1);   // (sąsiad, waga)
    for (int i = 0; i < m; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});
        g[b].push_back({a, w});                // nieskierowany
    }

    vector<ll> dist(n + 1, INF);
    vector<int> par(n + 1, 0);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;   // MIN-kopiec
    dist[1] = 0;
    pq.push({0, 1});
    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d > dist[v]) continue;             // nieaktualny wpis — pomijamy
        for (auto [u, w] : g[v]) {
            if (dist[v] + w < dist[u]) {
                dist[u] = dist[v] + w;
                par[u] = v;
                pq.push({dist[u], u});
            }
        }
    }

    for (int v = 1; v <= n; v++) cout << (dist[v] == INF ? -1 : dist[v]) << ' ';
    cout << '\n';
    if (dist[n] == INF) {
        cout << "BRAK\n";
        return 0;
    }
    vector<int> path;
    for (int v = n; v != 0; v = par[v]) path.push_back(v);   // par[1] == 0
    reverse(path.begin(), path.end());
    for (int v : path) cout << v << ' ';
    cout << '\n';
}

typedef long long ll;
const ll INF = LLONG_MAX / 4;

vector<ll> dijkstra(const vector<vector<pair<int, int>>>& g, int s) {
    vector<ll> dist(g.size(), INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, v] = pq.top(); pq.pop();
        if (d > dist[v]) continue;
        for (auto [u, w] : g[v])
            if (d + w < dist[u]) {
                dist[u] = d + w;
                pq.push({dist[u], u});
            }
    }
    return dist;
}

