typedef long long ll;
vector<ll> dijkstraSet(const vector<vector<pair<int,int>>>& g, int s) {
    vector<ll> dist(g.size(), LLONG_MAX);
    set<pair<ll,int>> st;
    dist[s] = 0; st.insert({0, s});
    while (!st.empty()) {
        auto [d, v] = *st.begin();
        st.erase(st.begin());
        for (auto [u, w] : g[v])
            if (d + w < dist[u]) {
                if (dist[u] != LLONG_MAX) st.erase({dist[u], u});
                dist[u] = d + w;
                st.insert({dist[u], u});
            }
    }
    return dist;
}

