typedef long long ll;
vector<ll> multiDijkstra(const vector<vector<pair<int,int>>>& g, const vector<int>& zrodla) {
    vector<ll> dist(g.size(), LLONG_MAX / 4);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<>> pq;
    for (int s : zrodla) { dist[s] = 0; pq.push({0, s}); }
    while (!pq.empty()) {
        auto [d, v] = pq.top(); pq.pop();
        if (d > dist[v]) continue;
        for (auto [u, w] : g[v])
            if (d + w < dist[u]) { dist[u] = d + w; pq.push({dist[u], u}); }
    }
    return dist;
}

