    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
    }
    vector<vector<ll>> dist(n + 1, vector<ll>(k + 1, INF));
    // stan w kopcu: (koszt, wierzchołek, użyte kupony)
    priority_queue<tuple<ll, int, int>, vector<tuple<ll, int, int>>, greater<>> pq;
    dist[1][0] = 0;
    pq.push({0, 1, 0});
    while (!pq.empty()) {
        auto [d, v, j] = pq.top();
        pq.pop();
        if (d > dist[v][j]) continue;
        for (auto [u, w] : g[v]) {
            if (d + w < dist[u][j]) {                 // zwykły przejazd
                dist[u][j] = d + w;
                pq.push({dist[u][j], u, j});
            }
            if (j < k && d < dist[u][j + 1]) {        // przejazd za darmo (kupon)
                dist[u][j + 1] = d;
                pq.push({d, u, j + 1});
            }
        }
    }
    ll ans = *min_element(dist[n].begin(), dist[n].end());
    cout << (ans == INF ? -1 : ans) << '\n';
}

