ll tankowanie(const vector<vector<pair<int,int>>>& g, const vector<int>& cena, int C, int s, int t) {
    int n = g.size();
    vector<vector<ll>> dist(n, vector<ll>(C + 1, LLONG_MAX));
    priority_queue<tuple<ll,int,int>, vector<tuple<ll,int,int>>, greater<>> pq;
    dist[s][0] = 0; pq.push({0, s, 0});
    while (!pq.empty()) {
        auto [d, v, f] = pq.top(); pq.pop();
        if (d > dist[v][f]) continue;
        if (v == t) return d;
        if (f < C && d + cena[v] < dist[v][f + 1]) {
            dist[v][f + 1] = d + cena[v];
            pq.push({dist[v][f + 1], v, f + 1});
        }
        for (auto [u, w] : g[v])
            if (f >= w && d < dist[u][f - w]) { dist[u][f - w] = d; pq.push({d, u, f - w}); }
    }
    return -1;
}

