    for (auto& [a, b, w] : e) cin >> a >> b >> w;

    vector<ll> dist(n + 1, INF);
    dist[1] = 0;
    for (int it = 0; it < n - 1; it++) {
        bool zmiana = false;
        for (auto [a, b, w] : e)
            if (dist[a] != INF && dist[a] + w < dist[b]) {
                dist[b] = dist[a] + w;
                zmiana = true;
            }
        if (!zmiana) break;                // wcześniejsze zakończenie
    }
    for (auto [a, b, w] : e)               // runda kontrolna
        if (dist[a] != INF && dist[a] + w < dist[b]) {
            cout << "UJEMNY CYKL\n";
            return 0;
        }
