// Odtworzenie ujemnego cyklu: wierzchołek poprawiony w n-tej rundzie + n kroków wstecz po par.
typedef long long ll;
vector<int> ujemnyCykl(int n, const vector<array<ll, 3>>& e) {
    vector<ll> dist(n + 1, 0);              // 0 wszędzie = wirtualne źródło -> cykl gdziekolwiek
    vector<int> par(n + 1, 0);
    int x = -1;
    for (int it = 0; it < n; it++) {
        x = -1;
        for (auto [a, b, w] : e)
            if (dist[a] + w < dist[b]) { dist[b] = dist[a] + w; par[b] = a; x = b; }
    }
    if (x == -1) return {};                 // brak ujemnego cyklu
    for (int i = 0; i < n; i++) x = par[x]; // na pewno jesteśmy na cyklu
    vector<int> cyc;
    for (int v = x;; v = par[v]) {
        cyc.push_back(v);
        if (v == x && cyc.size() > 1) break;
    }
    reverse(cyc.begin(), cyc.end());
    return cyc;                             // x, ..., x
}

