    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});          // skierowany
    }
    vector<ll> dist(n + 1, INF);
    vector<int> len(n + 1, 0);           // liczba krawędzi bieżącej najkrótszej ścieżki
    vector<bool> inq(n + 1, false);
    queue<int> q;
    dist[1] = 0;
    q.push(1);
    inq[1] = true;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        inq[v] = false;
        for (auto [u, w] : g[v]) {
            if (dist[v] + w < dist[u]) {
                dist[u] = dist[v] + w;
                len[u] = len[v] + 1;
                if (len[u] >= n) {       // ścieżka z n krawędziami => ujemny cykl
                    cout << "UJEMNY CYKL\n";
                    return 0;
                }
                if (!inq[u]) { inq[u] = true; q.push(u); }
            }
        }
