// Wagi >= 0: Dijkstra — gwarantowane O(m log n)
vector<ll> dijkstra(const vector<vector<pair<int,int>>>& g, int s) {
    vector<ll> d(g.size(), LLONG_MAX / 4);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<>> pq;
    d[s] = 0; pq.push({0, s});
    while (!pq.empty()) {
        auto [dv, v] = pq.top(); pq.pop();
        if (dv > d[v]) continue;
        for (auto [u, w] : g[v]) if (dv + w < d[u]) { d[u] = dv + w; pq.push({d[u], u}); }
    }
    return d;
}
