    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int best = INT_MAX;
    vector<int> dist(n + 1), par(n + 1);
    for (int s = 1; s <= n; s++) {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        dist[s] = 0;
        par[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int u : g[v]) {
                if (dist[u] == -1) {
                    dist[u] = dist[v] + 1;
                    par[u] = v;
                    q.push(u);
                } else if (par[v] != u) {          // krawędź spoza drzewa BFS
                    best = min(best, dist[v] + dist[u] + 1);
                }
            }
        }
    }
    cout << (best == INT_MAX ? -1 : best) << '\n';
}

