const int LOG = 30;                       // k < 2^30 (dla k <= 10^18 weź 60 i long long)

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<array<int, LOG>> up(n + 1);    // up[v][j] = wierzchołek po 2^j krokach z v
    for (int v = 1; v <= n; v++) cin >> up[v][0];
    for (int j = 1; j < LOG; j++)
        for (int v = 1; v <= n; v++)
            up[v][j] = up[up[v][j - 1]][j - 1];
    while (q--) {
        int v;
        long long k;
        cin >> v >> k;
        for (int j = 0; j < LOG; j++)
            if (k >> j & 1) v = up[v][j];
        cout << v << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

// Dla każdego v: długość cyklu, do którego dochodzi, i odległość od cyklu (0, gdy leży na cyklu).
int main() {
    int n;
    cin >> n;
    vector<int> f(n + 1);
    for (int v = 1; v <= n; v++) cin >> f[v];
    vector<int> state(n + 1, 0), pos(n + 1, -1), cyc(n + 1, 0), tail(n + 1, 0);
    for (int s = 1; s <= n; s++) {
        if (state[s]) continue;
        vector<int> path;
        int v = s;
        while (state[v] == 0) {           // idziemy, aż trafimy na coś odwiedzonego
            state[v] = 1;
            pos[v] = path.size();
            path.push_back(v);
            v = f[v];
        }
        if (state[v] == 1) {              // nowy cykl: od pozycji v do końca ścieżki
            int L = path.size() - pos[v];
            for (int i = pos[v]; i < (int)path.size(); i++) {
                cyc[path[i]] = L;
                tail[path[i]] = 0;
                state[path[i]] = 2;
            }
            path.resize(pos[v]);
        }
        for (int i = (int)path.size() - 1; i >= 0; i--) {   // ogon: od końca
            int u = path[i];
            cyc[u] = cyc[f[u]];
            tail[u] = tail[f[u]] + 1;
            state[u] = 2;
        }
    }
    for (int v = 1; v <= n; v++) cout << cyc[v] << ' ' << tail[v] << '\n';
}

