const int LOG = 60, MAXN = 100005;
int up[LOG][MAXN];
void build(int n, const vector<int>& f) {        // f[1..n]
    for (int v = 1; v <= n; v++) up[0][v] = f[v];
    for (int j = 1; j < LOG; j++)
        for (int v = 1; v <= n; v++) up[j][v] = up[j - 1][up[j - 1][v]];
}
int jump(int v, long long k) {
    for (int j = 0; j < LOG; j++)
        if (k >> j & 1LL) v = up[j][v];
    return v;
}

