#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<int> p(n + 1);
    for (int i = 1; i <= n; i++) cin >> p[i];
    vector<bool> vis(n + 1, false);
    long long nww = 1;
    int cykle = 0;
    for (int i = 1; i <= n; i++) {
        if (vis[i]) continue;
        cykle++;
        long long L = 0;
        for (int v = i; !vis[v]; v = p[v]) { vis[v] = true; L++; }
        nww = nww / __gcd(nww, L) * L;
    }
    cout << cykle << ' ' << nww << '\n';
}

